import{_ as r,a0 as a,w as s,s as n,I as l,x as e,a1 as o,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Suplemon：帶有多光標支持的現代 CLI 文本編輯器 | LCTT x X-CMD","titleTemplate":false,"description":"Suplemon：帶有多光標支持的現代 CLI 文本編輯器 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Suplemon：帶有多光標支持的現代 CLI 文本編輯器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Suplemon：帶有多光標支持的現代 CLI 文本編輯器 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171129 Suplemon - Modern CLI Text Editor with Multi Cursor Support","title":"Suplemon：帶有多光標支持的現代 CLI 文本編輯器","tag":"201712","desc":""},"relativePath":"201712/20171129 Suplemon - Modern CLI Text Editor with Multi Cursor Support.md","filePath":"[post].md"}'),u={name:"201712/20171129 Suplemon - Modern CLI Text Editor with Multi Cursor Support.md"};function h(c,t,m,g,C,b){const d=a("Link");return s(),n("div",null,[t[19]||(t[19]=l("h1",{id:"suplemon-帶有多光標支持的現代-cli-文本編輯器",tabindex:"-1"},[e("Suplemon：帶有多光標支持的現代 CLI 文本編輯器 "),l("a",{class:"header-anchor",href:"#suplemon-帶有多光標支持的現代-cli-文本編輯器","aria-label":"Permalink to “Suplemon：帶有多光標支持的現代 CLI 文本編輯器”"},"​")],-1)),l("p",null,[t[1]||(t[1]=e("Suplemon 是一個 CLI 中的現代文本編輯器，它模擬 ",-1)),o(d,{href:"https://linoxide.com/tools/install-sublime-text-editor-linux/"},{default:i(()=>[...t[0]||(t[0]=[e("Sublime Text",-1)])]),_:1}),t[2]||(t[2]=e(" 的多光標行為和其它特性。它是輕量級的，非常易於使用，就像 Nano 一樣。",-1))]),t[20]||(t[20]=l("p",null,"使用 CLI 編輯器的好處之一是，無論你使用的 Linux 發行版是否有 GUI，你都可以使用它。這種文本編輯器也很簡單、快速和強大。",-1)),l("p",null,[t[4]||(t[4]=e("你可以在其",-1)),o(d,{href:"https://github.com/richrd/suplemon/"},{default:i(()=>[...t[3]||(t[3]=[e("官方倉庫",-1)])]),_:1}),t[5]||(t[5]=e("中找到有用的信息和源代碼。",-1))]),t[21]||(t[21]=p('<h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><p>這些是一些它有趣的功能：</p><ul><li>多光標支持</li><li>撤銷/重做</li><li>複製和粘貼，帶有多行支持</li><li>鼠標支持</li><li>擴展</li><li>查找、查找所有、查找下一個</li><li>語法高亮</li><li>自動完成</li><li>自定義鍵盤快捷鍵</li></ul><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>首先，確保安裝了最新版本的 python3 和 pip3。</p><p>然後在終端輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pip3 install suplemon</span></span></code></pre></div><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><h4 id="在當前目錄中創建一個新文件" tabindex="-1">在當前目錄中創建一個新文件 <a class="header-anchor" href="#在當前目錄中創建一個新文件" aria-label="Permalink to “在當前目錄中創建一個新文件”">​</a></h4><p>打開一個終端並輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ suplemon</span></span></code></pre></div><p>你將看到如下：</p><p><img src="https://linoxide.com/wp-content/uploads/2017/11/suplemon-new-file.png" alt="suplemon new file"></p><h4 id="打開一個或多個文件" tabindex="-1">打開一個或多個文件 <a class="header-anchor" href="#打開一個或多個文件" aria-label="Permalink to “打開一個或多個文件”">​</a></h4><p>打開一個終端並輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ suplemon &lt;filename1&gt; &lt;filename2&gt; ... &lt;filenameN&gt;</span></span></code></pre></div><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ suplemon example1.c example2.c</span></span></code></pre></div><h3 id="主要配置" tabindex="-1">主要配置 <a class="header-anchor" href="#主要配置" aria-label="Permalink to “主要配置”">​</a></h3><p>你可以在 <code>~/.config/suplemon/suplemon-config.json</code> 找到配置文件。</p><p>編輯這個文件很簡單，你只需要進入命令模式（進入 suplemon 後）並運行 <code>config</code> 命令。你可以通過運行 <code>config defaults</code> 來查看默認配置。</p><h4 id="鍵盤映射配置" tabindex="-1">鍵盤映射配置 <a class="header-anchor" href="#鍵盤映射配置" aria-label="Permalink to “鍵盤映射配置”">​</a></h4><p>我會展示 suplemon 的默認鍵映射。如果你想編輯它們，只需運行 <code>keymap</code> 命令。運行 <code>keymap default</code> 來查看默認的鍵盤映射文件。</p><div class="table-wrap"><table><thead><tr><th>操作</th><th>快捷鍵</th></tr></thead><tbody><tr><td>退出</td><td><code>Ctrl + Q</code></td></tr><tr><td>複製行到緩衝區</td><td><code>Ctrl + C</code></td></tr><tr><td>剪切行緩衝區</td><td><code>Ctrl + X</code></td></tr><tr><td>插入緩衝區</td><td><code>Ctrl + V</code></td></tr><tr><td>複製行</td><td><code>Ctrl + K</code></td></tr><tr><td>跳轉</td><td><code>Ctrl + G</code>。 你可以跳轉到一行或一個文件（只需鍵入一個文件名的開頭）。另外，可以輸入類似於 <code>exam:50</code> 跳轉到 <code>example.c</code> 第 <code>50</code> 行。</td></tr><tr><td>用字符串或正則表達式搜索</td><td><code>Ctrl + F</code></td></tr><tr><td>搜索下一個</td><td><code>Ctrl + D</code></td></tr><tr><td>去除空格</td><td><code>Ctrl + T</code></td></tr><tr><td>在箭頭方向添加新的光標</td><td><code>Alt + 方向鍵</code></td></tr><tr><td>跳轉到上一個或下一個單詞或行</td><td><code>Ctrl + 左/右</code></td></tr><tr><td>恢復到單光標/取消輸入提示</td><td><code>Esc</code></td></tr><tr><td>向上/向下移動行</td><td><code>Page Up</code> / <code>Page Down</code></td></tr><tr><td>保存文件</td><td><code>Ctrl + S</code></td></tr><tr><td>用新名稱保存文件</td><td><code>F1</code></td></tr><tr><td>重新載入當前文件</td><td><code>F2</code></td></tr><tr><td>打開文件</td><td><code>Ctrl + O</code></td></tr><tr><td>關閉文件</td><td><code>Ctrl + W</code></td></tr><tr><td>切換到下一個/上一個文件</td><td><code>Ctrl + Page Up</code> / <code>Ctrl + Page Down</code></td></tr><tr><td>運行一個命令</td><td><code>Ctrl + E</code></td></tr><tr><td>撤消</td><td><code>Ctrl + Z</code></td></tr><tr><td>重做</td><td><code>Ctrl + Y</code></td></tr><tr><td>觸發可見的空格</td><td><code>F7</code></td></tr><tr><td>切換鼠標模式</td><td><code>F8</code></td></tr><tr><td>顯示行號</td><td><code>F9</code></td></tr><tr><td>顯示全屏</td><td><code>F11</code></td></tr></tbody></table></div><h4 id="鼠標快捷鍵" tabindex="-1">鼠標快捷鍵 <a class="header-anchor" href="#鼠標快捷鍵" aria-label="Permalink to “鼠標快捷鍵”">​</a></h4><ul><li>將光標置於指針位置：左鍵單擊</li><li>在指針位置添加一個光標：右鍵單擊</li><li>垂直滾動：向上/向下滾動滾輪</li></ul><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在嘗試 Suplemon 一段時間後，我改變了對 CLI 文本編輯器的看法。我以前曾經嘗試過 Nano，是的，我喜歡它的簡單性，但是它的現代特徵的缺乏使它在日常使用中變得不實用。</p><p>這個工具有 CLI 和 GUI 世界最好的東西……簡單性和功能豐富！所以我建議你試試看，並在評論中寫下你的想法 😃</p><hr>',30)),l("p",null,[t[7]||(t[7]=e("via: ",-1)),o(d,{href:"https://linoxide.com/tools/suplemon-cli-text-editor-multi-cursor/"},{default:i(()=>[...t[6]||(t[6]=[e("https://linoxide.com/tools/suplemon-cli-text-editor-multi-cursor/",-1)])]),_:1})]),l("p",null,[t[11]||(t[11]=e("作者：",-1)),o(d,{href:"https://linoxide.com/author/ursinov/"},{default:i(()=>[...t[8]||(t[8]=[e("Ivo Ursino",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),o(d,{href:"https://github.com/geekpi"},{default:i(()=>[...t[9]||(t[9]=[e("geekpi",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),o(d,{href:"https://github.com/wxy"},{default:i(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創編譯，",-1)),o(d,{href:"https://linux.cn/"},{default:i(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const T=r(u,[["render",h]]);export{x as __pageData,T as default};
